    <circle cx="509" cy="63" r="145" className="fill-chart-1/25" />
    <circle cx="92" cy="283" r="169" className="fill-chart-2/20" />
    <rect
      x="125"
      y="72"
      width="390"
      height="190"
      rx="16"
